CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(
 id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE,
 display_name TEXT NOT NULL DEFAULT '', verified_at TEXT,
 notifications_enabled INTEGER NOT NULL DEFAULT 1 CHECK(notifications_enabled IN (0,1)),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS challenges(email TEXT PRIMARY KEY, code_hash TEXT NOT NULL, expires REAL NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, requested REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY, started REAL NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS listings(
 id INTEGER PRIMARY KEY, creator_id INTEGER REFERENCES users(id), type TEXT NOT NULL CHECK(type IN ('LOST','FOUND')),
 title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',private_description TEXT NOT NULL DEFAULT '',
 category TEXT NOT NULL DEFAULT 'other',attributes TEXT NOT NULL DEFAULT '{}',
 campus TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',private_location TEXT NOT NULL DEFAULT '',
 occurred_at TEXT NOT NULL,visibility TEXT NOT NULL DEFAULT 'PUBLIC' CHECK(visibility IN ('PUBLIC','PRIVATE')),
 status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLAIMED','RETURNED','CLOSED')),
 resolution TEXT, reward REAL NOT NULL DEFAULT 0 CHECK(reward>=0),
 custody TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(custody IN ('UNKNOWN','FINDER','DROP_OFF_REPORTED','RETURNED')),
 custody_note TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS listings_creator ON listings(creator_id);
CREATE INDEX IF NOT EXISTS listings_active ON listings(status,type,visibility);
CREATE TABLE IF NOT EXISTS images(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL REFERENCES listings(id),storage_name TEXT NOT NULL UNIQUE,
 is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN (0,1)),width INTEGER NOT NULL,height INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS potential_locations(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
 label TEXT NOT NULL,latitude REAL NOT NULL,longitude REAL NOT NULL,priority REAL NOT NULL DEFAULT 1,
 share_public INTEGER NOT NULL DEFAULT 0 CHECK(share_public IN (0,1)));
CREATE TABLE IF NOT EXISTS matches(id INTEGER PRIMARY KEY,lost_id INTEGER NOT NULL REFERENCES listings(id),found_id INTEGER NOT NULL REFERENCES listings(id),
 score REAL NOT NULL,reasons TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(lost_id,found_id));
CREATE TABLE IF NOT EXISTS match_feedback(match_id INTEGER NOT NULL REFERENCES matches(id),user_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL,PRIMARY KEY(match_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,
 resource_id INTEGER NOT NULL,message TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS claims(id INTEGER PRIMARY KEY,found_id INTEGER NOT NULL REFERENCES listings(id),lost_id INTEGER REFERENCES listings(id),
 claimant_id INTEGER NOT NULL REFERENCES users(id),evidence TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','NEEDS_INFO','ACCEPTED','REJECTED','CANCELLED','COMPLETED')),
 review_note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_claim_per_user ON claims(found_id,claimant_id) WHERE status IN ('PENDING','NEEDS_INFO','ACCEPTED');
CREATE UNIQUE INDEX IF NOT EXISTS one_accepted_found ON claims(found_id) WHERE status='ACCEPTED';
CREATE UNIQUE INDEX IF NOT EXISTS one_accepted_lost ON claims(lost_id) WHERE status='ACCEPTED' AND lost_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,claim_id INTEGER NOT NULL REFERENCES claims(id),sender_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS handoffs(id INTEGER PRIMARY KEY,claim_id INTEGER NOT NULL UNIQUE REFERENCES claims(id),
 method TEXT NOT NULL CHECK(method IN ('MEETUP','STAFFED_DROP_OFF')),place TEXT NOT NULL,arranged_at TEXT,
 finder_confirmed INTEGER NOT NULL DEFAULT 0,owner_confirmed INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','COMPLETED','CANCELLED')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reputation_events(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),handoff_id INTEGER NOT NULL REFERENCES handoffs(id),points INTEGER NOT NULL,reason TEXT NOT NULL,UNIQUE(user_id,handoff_id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL REFERENCES listings(id),actor_id INTEGER REFERENCES users(id),kind TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recording_sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,consented_at REAL NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS location_points(id INTEGER PRIMARY KEY,session_id INTEGER NOT NULL REFERENCES recording_sessions(id) ON DELETE CASCADE,
 latitude REAL NOT NULL,longitude REAL NOT NULL,accuracy REAL NOT NULL,recorded_at REAL NOT NULL,UNIQUE(session_id,recorded_at));
CREATE TABLE IF NOT EXISTS ai_analyses(id INTEGER PRIMARY KEY,listing_id INTEGER NOT NULL REFERENCES listings(id),user_id INTEGER NOT NULL REFERENCES users(id),
 kind TEXT NOT NULL,mode TEXT NOT NULL,listing_version INTEGER NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_runs(source_hash TEXT PRIMARY KEY,imported_count INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS listing_vectors(listing_id INTEGER PRIMARY KEY REFERENCES listings(id),listing_version INTEGER NOT NULL,model TEXT NOT NULL,vector TEXT NOT NULL);
